  const { order } = req.body;
  if (!Array.isArray(order) || !order.every(v => typeof v === 'string')) {
    return res.status(400).json({ error: 'order must be a string[]' });
  }
  saveCategoryOrder(order);
  res.json({ ok: true, order });
});

