// ── Section parser ───────────────────────────────────────────────────────────
// Splits a body into H2-level sections: { heading, headingLevel, startLine,
// endLine, lines: [...], text: '...' }. Fenced code blocks are respected so we
// don't misparse '```## foo' inside examples.
function parseSections(bodyLines) {
  const sections = [];
  let current = { heading: '(preamble)', headingLevel: 0, startLine: 0, lines: [] };
  let inFence = false;

  for (let i = 0; i < bodyLines.length; i++) {
    const line = bodyLines[i];
    const fence = line.match(/^```/);
    if (fence) inFence = !inFence;

    if (!inFence) {
