// Preserve prior manifest. If the frontmatter's skills list is out-of-sync
// with what's on disk (common after repeated --write runs before the merge
// fix landed), reconcile from disk — scan ~/.claude/skills/<agent>/ and
// synthesize entries for every file. This is always safe: a healthy agent
// produces an identical manifest.
let existingSkillManifest = Array.isArray(parsed.data?.skills) ? parsed.data.skills : [];
if (existingSkillManifest.length !== onDiskCount || args.reconcile || args.force) {
  existingSkillManifest = reconcileManifestFromDisk(agent, existingSkillManifest);
}

