// Agent health score — deterministic, explainable, 0-100.
//
// Signals (rolling 14-day window):
//   1. agent_runs.status  → success vs error count
//   2. witness_log.class  → SUCCESS / FAILURE / ANTIPATTERN / REGRESSION / TIMEOUT
//   3. daily_scores       → rolled-up daily totals (antipatterns, regressions)
//   4. registry.status    → active / probation / pip / retired
//   5. lastRunAt          → stale agents (>30d) take a small hit
//
// Formula (transparent, single pass):
//   score = 100
//   - min(40, recentFailures * 4)      # max 40 for failed runs
//   - min(30, antipatterns   * 6)      # max 30 for antipatterns
//   - min(20, regressions    * 10)     # max 20 for regressions
//   - statusPenalty(status)            # probation -10, pip -20, retired -50
//   - stalePenalty(lastRunAt)          # >30d no run = -10
//   = max(0, score)
//
// Band:
//   >=80  green  (healthy)
//   60-79 amber  (warn)
//   <60   red    (action)
//
// Cold-start: agents with no data at all (totalRuns=0) score 85 "new — no data"
// so they don't look failing just because they haven't run yet.

const WINDOW_DAYS = 14;
const STALE_DAYS = 30;

function statusPenalty(status) {
  switch (status) {
    case 'pip': return 20;
    case 'probation': return 10;
    case 'retired': return 50;
    default: return 0;
  }
}

function band(score) {
  if (score >= 80) return 'healthy';
  if (score >= 60) return 'warn';
  return 'action';
}

// Main computer. Accepts a db-like handle exposing `prepare(sql).all(args)`
// (better-sqlite3 style). Returns map: { agentId -> health }.
// Single batched query, zero per-agent round-trips.
function computeAllHealth(db, { agentIds = null } = {}) {
  const windowISO = new Date(Date.now() - WINDOW_DAYS * 86400_000).toISOString();

  // 1. agent_runs in window
  const runRows = db.prepare(
    `SELECT agentName as agent,
            SUM(CASE WHEN status = 'success' THEN 1 ELSE 0 END) as successes,
            SUM(CASE WHEN status != 'success' THEN 1 ELSE 0 END) as failures,
            MAX(timestamp) as lastRunAt
       FROM agent_runs
      WHERE timestamp >= ?
      GROUP BY agentName`
  ).all(windowISO);

  // 2. witness_log in window — break out failure modes
  const witnessRows = db.prepare(
    `SELECT agent,
            SUM(CASE WHEN class = 'SUCCESS'     THEN 1 ELSE 0 END) as wSuccess,
            SUM(CASE WHEN class = 'FAILURE'     THEN 1 ELSE 0 END) as wFailure,
            SUM(CASE WHEN class = 'TIMEOUT'     THEN 1 ELSE 0 END) as wTimeout,
            SUM(CASE WHEN class = 'ANTIPATTERN' THEN 1 ELSE 0 END) as wAntipattern,
            SUM(CASE WHEN class = 'REGRESSION'  THEN 1 ELSE 0 END) as wRegression
       FROM witness_log
      WHERE t >= ?
      GROUP BY agent`
  ).all(windowISO);

  // 3. daily_scores — last-window aggregate. More authoritative when present
  //    since it's what the HR pipeline uses for reviews.
  const windowDateCutoff = new Date(Date.now() - WINDOW_DAYS * 86400_000).toISOString().slice(0, 10);
  let dailyRows = [];
  try {
    dailyRows = db.prepare(
      `SELECT agent,
              SUM(success) as dSuccess,
              SUM(failure) as dFailure,
              SUM(antipattern) as dAntipattern,
              SUM(regression) as dRegression
         FROM daily_scores
        WHERE date >= ?
        GROUP BY agent`
    ).all(windowDateCutoff);
  } catch { /* table optional */ }

  // Merge by agent
  const by = new Map();
  const touch = (id) => {
    if (!by.has(id)) by.set(id, {
      successes: 0, failures: 0, antipatterns: 0, regressions: 0,
      timeouts: 0, lastRunAt: null,
    });
    return by.get(id);
  };

  for (const r of runRows) {
    const a = touch(r.agent);
    a.successes += r.successes || 0;
    a.failures += r.failures || 0;
    if (r.lastRunAt && (!a.lastRunAt || r.lastRunAt > a.lastRunAt)) a.lastRunAt = r.lastRunAt;
  }
  for (const w of witnessRows) {
    const a = touch(w.agent);
    a.successes += w.wSuccess || 0;
    a.failures += (w.wFailure || 0) + (w.wTimeout || 0);
    a.antipatterns += w.wAntipattern || 0;
    a.regressions += w.wRegression || 0;
    a.timeouts += w.wTimeout || 0;
  }
  for (const d of dailyRows) {
    const a = touch(d.agent);
    // daily_scores take precedence for antipatterns/regressions (authoritative)
    a.antipatterns = Math.max(a.antipatterns, d.dAntipattern || 0);
    a.regressions = Math.max(a.regressions, d.dRegression || 0);
  }

  // Build result map
  const out = {};
  const targetIds = agentIds || [...by.keys()];
  for (const id of targetIds) {
    const s = by.get(id) || { successes: 0, failures: 0, antipatterns: 0, regressions: 0, timeouts: 0, lastRunAt: null };
    out[id] = buildHealth(id, s);
  }

  return out;
}

function buildHealth(agentId, signals, registryStatus = null) {
  const totalRuns = (signals.successes || 0) + (signals.failures || 0);

  // Cold-start: no data → neutral 85 with note
  if (totalRuns === 0 && !signals.antipatterns && !signals.regressions) {
    return {
      score: 85,
      band: band(85),
      totalRuns: 0,
      successes: 0,
      failures: 0,
      antipatterns: 0,
      regressions: 0,
      lastRunAt: null,
      cold: true,
      reasons: ['new — no recent run data'],
    };
  }

  let score = 100;
  const reasons = [];

  const failPenalty = Math.min(40, (signals.failures || 0) * 4);
  if (failPenalty > 0) { score -= failPenalty; reasons.push(`-${failPenalty} (${signals.failures} failed runs)`); }

  const apPenalty = Math.min(30, (signals.antipatterns || 0) * 6);
  if (apPenalty > 0) { score -= apPenalty; reasons.push(`-${apPenalty} (${signals.antipatterns} antipatterns)`); }

  const regPenalty = Math.min(20, (signals.regressions || 0) * 10);
  if (regPenalty > 0) { score -= regPenalty; reasons.push(`-${regPenalty} (${signals.regressions} regressions)`); }

  const statusPen = statusPenalty(registryStatus);
  if (statusPen > 0) { score -= statusPen; reasons.push(`-${statusPen} (status: ${registryStatus})`); }

  // Stale bonus penalty
  if (signals.lastRunAt) {
    const ageMs = Date.now() - new Date(signals.lastRunAt).getTime();
    const ageDays = ageMs / 86400_000;
    if (ageDays > STALE_DAYS) {
      score -= 10;
      reasons.push(`-10 (stale: last run ${Math.round(ageDays)}d ago)`);
    }
  }

  score = Math.max(0, Math.round(score));
  return {
    score,
    band: band(score),
    totalRuns,
    successes: signals.successes || 0,
    failures: signals.failures || 0,
    antipatterns: signals.antipatterns || 0,
    regressions: signals.regressions || 0,
    lastRunAt: signals.lastRunAt,
    cold: false,
    reasons: reasons.length > 0 ? reasons : ['no issues'],
  };
}

// Enrich per-agent using the registry status (passed separately because it
// lives in a different store).
function withRegistryStatus(healthMap, registryById) {
  for (const id of Object.keys(healthMap)) {
    const rec = registryById?.[id];
    const status = rec?.status || null;
    if (!status) continue;
    const pen = statusPenalty(status);
    if (pen > 0 && !healthMap[id].cold) {
      healthMap[id].score = Math.max(0, healthMap[id].score - pen);
      healthMap[id].band = band(healthMap[id].score);
      healthMap[id].reasons.push(`-${pen} (status: ${status})`);
    }
    healthMap[id].status = status;
  }
  return healthMap;
}

module.exports = { computeAllHealth, withRegistryStatus, buildHealth };

