  const config = loadConfig();
  const projects = discoverProjects(config.projectDirs);

  // Load org data (registry + departments) — enrich each agent with
  // level / levelTitle / yearsOfExperience / tier / department / leader flag
  // so the UI doesn't need a second request per row.
  const orgMod = require('./org');
