552	          const agents = listAgents(path.join(projectPath, '.claude', 'agents'));
553	          const commands = listMdFiles(path.join(projectPath, '.claude', 'commands'));
554	          const rules = listMdFiles(path.join(projectPath, '.claude', 'rules'));
555	          projects.push({
556	            id: Buffer.from(projectPath).toString('base64url'),
557	            name: entry.name,
