// ── Knowledge Graph ────────────────────────────────────────────────────────────
// GET /api/knowledge-graph
// Returns a Graphify-style node+edge graph of the entire agent workforce.
// Nodes: agents (+ optional skill nodes from frontmatter.skills[]).
// Edges:
//   EXTRACTED — reportsTo hierarchy (confidence 1.0, solid)
//   INFERRED  — owns_skill from frontmatter.skills[] (confidence 0.8, dashed)
//   INFERRED  — skill_overlap between agents sharing ≥2 registry skill domains (jaccard, dashed)
app.get('/api/knowledge-graph', (req, res) => {
  try {
    const orgMod = require('./org');
    let registryById = {};
    let departmentsById = {};
    let departmentsData = { departments: {}, phases: {} };
    try {
      const registry = orgMod.loadRegistry();
      registryById = registry?.agents || {};
      departmentsData = orgMod.loadDepartments() || departmentsData;
      departmentsById = departmentsData.departments || {};
    } catch { /* degrade gracefully */ }

    // Assign community index per department (0 = largest by member count)
    const deptIds = Object.keys(departmentsById);
    const deptMemberCount = {};
    for (const agent of Object.values(registryById)) {
      const d = agent.department;
      if (d) deptMemberCount[d] = (deptMemberCount[d] || 0) + 1;
    }
    const deptsBySize = deptIds.slice().sort((a, b) => (deptMemberCount[b] || 0) - (deptMemberCount[a] || 0));
    const deptCommunity = {};
    deptsBySize.forEach((d, i) => { deptCommunity[d] = i; });

    // Build agent nodes
    const agents = listAgents(path.join(CLAUDE_DIR, 'agents'));
    const nodes = [];
    const agentSkillMap = {}; // agentId → Set<skillDomain> for overlap detection

    for (const agent of agents) {
      const agentId = agent.filename.replace(/\.md$/, '');
      const rec = registryById[agentId] || null;
      const dept = rec?.department || null;
      const deptInfo = dept ? departmentsById[dept] : null;

      // Skill domains from registry (keys of skills object)
      const skillDomains = rec?.skills ? Object.keys(rec.skills) : [];
      agentSkillMap[agentId] = new Set(skillDomains);

      nodes.push({
        id: agentId,
        type: 'agent',
        label: rec?.title ? `${agentId}` : agentId,
        name: agent.name,
        title: rec?.title || null,
        department: dept,
        departmentLabel: deptInfo?.label || dept,
        departmentColor: deptInfo?.color || '#6b7280',
        community: dept !== null ? (deptCommunity[dept] ?? 99) : 99,
        level: rec?.level ?? null,
        levelTitle: rec?.levelTitle ?? null,
        tier: rec?.tier || null,
        status: rec?.status || 'active',
        model: agent.model || 'sonnet',
        description: agent.description || '',
        yearsOfExperience: rec?.yearsOfExperience ?? null,
        experiencePoints: rec?.experiencePoints ?? null,
        reportsTo: rec?.reportsTo || null,
        skillCount: skillDomains.length,
        // skills manifest from frontmatter (compacted skill files)
        skillFiles: Array.isArray(agent.frontmatter?.skills)
          ? agent.frontmatter.skills.map(s => s.id || s.path)
          : [],
        degree: 0, // computed below
      });
    }

    // Build edges
    const edges = [];

    // 1. EXTRACTED: reportsTo hierarchy
    for (const n of nodes) {
      if (n.reportsTo) {
        edges.push({
          id: `reports:${n.id}→${n.reportsTo}`,
          source: n.id,
          target: n.reportsTo,
          relation: 'reports_to',
          confidence: 'EXTRACTED',
          confidence_score: 1.0,
          dashed: false,
        });
      }
    }

    // 2. INFERRED: skill_overlap — agents sharing ≥2 skill domains
    const agentIds = nodes.map(n => n.id);
    for (let i = 0; i < agentIds.length; i++) {
      for (let j = i + 1; j < agentIds.length; j++) {
        const a = agentIds[i];
        const b = agentIds[j];
        const setA = agentSkillMap[a] || new Set();
        const setB = agentSkillMap[b] || new Set();
        const intersection = [...setA].filter(x => setB.has(x));
        const union = new Set([...setA, ...setB]);
        if (intersection.length >= 2 && union.size > 0) {
          const jaccard = intersection.length / union.size;
          edges.push({
            id: `overlap:${a}↔${b}`,
            source: a,
            target: b,
            relation: 'skill_overlap',
            confidence: 'INFERRED',
            confidence_score: Math.round(jaccard * 100) / 100,
            dashed: true,
            sharedSkills: intersection.slice(0, 5), // top 5 for tooltip
          });
        }
      }
    }

    // 3. INFERRED: owns_skill from frontmatter.skills[] (skill file nodes)
    const skillNodes = [];
    const seenSkillIds = new Set();
    for (const agent of agents) {
      const agentId = agent.filename.replace(/\.md$/, '');
      const manifest = Array.isArray(agent.frontmatter?.skills) ? agent.frontmatter.skills : [];
      for (const skill of manifest) {
        const skillId = `skill:${skill.id || skill.path}`;
        if (!seenSkillIds.has(skillId)) {
          seenSkillIds.add(skillId);
          skillNodes.push({
            id: skillId,
            type: 'skill',
            label: (skill.id || skill.path || '').replace(/-/g, ' '),
            rawId: skill.id || '',
            path: skill.path || '',
            lines: skill.lines || 0,
            department: null,
            departmentColor: '#4b5563',
            community: 98,
            degree: 0,
          });
        }
        edges.push({
          id: `skill:${agentId}→${skillId}`,
          source: agentId,
          target: skillId,
          relation: 'owns_skill',
          confidence: 'INFERRED',
          confidence_score: 0.8,
          dashed: true,
        });
      }
    }

    // Compute degree per node
    const degreeMap = {};
    for (const e of edges) {
      degreeMap[e.source] = (degreeMap[e.source] || 0) + 1;
      degreeMap[e.target] = (degreeMap[e.target] || 0) + 1;
    }
    for (const n of nodes) n.degree = degreeMap[n.id] || 0;
    for (const n of skillNodes) n.degree = degreeMap[n.id] || 0;

    // Stats
    const allNodes = [...nodes, ...skillNodes];
    const extracted = edges.filter(e => e.confidence === 'EXTRACTED').length;
    const inferred = edges.filter(e => e.confidence === 'INFERRED').length;

    res.json({
      nodes: allNodes,
      edges,
      stats: {
        totalAgents: nodes.length,
        totalSkillNodes: skillNodes.length,
        totalNodes: allNodes.length,
        totalEdges: edges.length,
        byConfidence: { EXTRACTED: extracted, INFERRED: inferred },
        communities: deptsBySize.length,
        byRelation: {
          reports_to: edges.filter(e => e.relation === 'reports_to').length,
          skill_overlap: edges.filter(e => e.relation === 'skill_overlap').length,
          owns_skill: edges.filter(e => e.relation === 'owns_skill').length,
        },
      },
      departments: departmentsById,
    });
  } catch (err) {
    res.status(500).json({ error: err.message || 'Knowledge graph build failed' });
  }
});

