'use strict';

const { Router } = require('express');
const path = require('path');
const os = require('os');
const { rateLimit } = require('../middleware/rateLimit');
const { listAgents } = require('../lib/cache');
const org = require('../org');

const router = Router();

const HOME = os.homedir();
const CLAUDE_DIR = path.join(HOME, '.claude');

// GET /api/knowledge-graph
// Returns a Graphify-style node+edge intelligence map of the agent workforce.
//
// Node types:
//   agent — every agent in ~/.claude/agents/
//   skill — skill files referenced in agent frontmatter.skills[]
//
// Edge types + confidence:
//   reports_to   EXTRACTED  1.0  solid  — from registry.reportsTo
//   owns_skill   INFERRED   0.8  dashed — from frontmatter.skills[] manifest
//   skill_overlap INFERRED  jaccard dashed — agents sharing ≥2 registry skill domains
router.get('/knowledge-graph', rateLimit('read'), (req, res) => {
  try {
    let registryById = {};
    let departmentsById = {};

    try {
      const registry = org.loadRegistry();
      registryById = registry?.agents || {};
      const deps = org.loadDepartments();
      departmentsById = deps?.departments || {};
    } catch { /* degrade gracefully */ }

    // Community index: 0 = largest department by member count (mirrors Graphify's Leiden output)
    const deptMemberCount = {};
    for (const agent of Object.values(registryById)) {
      const d = agent.department;
      if (d) deptMemberCount[d] = (deptMemberCount[d] || 0) + 1;
    }
    const deptsBySize = Object.keys(departmentsById)
      .sort((a, b) => (deptMemberCount[b] || 0) - (deptMemberCount[a] || 0));
    const deptCommunity = {};
    deptsBySize.forEach((d, i) => { deptCommunity[d] = i; });

    // ── Agent nodes ────────────────────────────────────────────────────────────
    const agents = listAgents(path.join(CLAUDE_DIR, 'agents'));
    const agentNodes = [];
    const agentSkillDomains = {}; // agentId → Set<domain> for overlap computation

    for (const agent of agents) {
      const agentId = agent.filename.replace(/\.md$/, '');
      const rec = registryById[agentId] || null;
      const dept = rec?.department || null;
      const deptInfo = dept ? departmentsById[dept] : null;

      const skillDomains = rec?.skills ? Object.keys(rec.skills) : [];
      agentSkillDomains[agentId] = new Set(skillDomains);

      agentNodes.push({
        id: agentId,
        type: 'agent',
        label: agent.name || agentId,
        department: dept,
        departmentLabel: deptInfo?.label || dept || 'Unassigned',
        departmentColor: deptInfo?.color || '#6b7280',
        community: dept !== null ? (deptCommunity[dept] ?? 99) : 99,
        level: rec?.level ?? null,
        levelTitle: rec?.levelTitle ?? null,
        tier: rec?.tier || null,
        status: rec?.status || 'active',
        model: agent.model || 'sonnet',
        description: agent.description || '',
        yearsOfExperience: rec?.yearsOfExperience ?? null,
        experiencePoints: rec?.experiencePoints ?? null,
        reportsTo: rec?.reportsTo || null,
        registeredSkillCount: skillDomains.length,
        skillFileCount: Array.isArray(agent.frontmatter?.skills) ? agent.frontmatter.skills.length : 0,
        degree: 0, // computed after edges
      });
    }

    // ── Edges ──────────────────────────────────────────────────────────────────
    const edges = [];
    const agentIdSet = new Set(agentNodes.map(n => n.id));

    // 1. EXTRACTED: reportsTo hierarchy
    for (const n of agentNodes) {
      if (n.reportsTo && agentIdSet.has(n.reportsTo)) {
        edges.push({
          id: `reports:${n.id}→${n.reportsTo}`,
          source: n.id,
          target: n.reportsTo,
          relation: 'reports_to',
          confidence: 'EXTRACTED',
          confidence_score: 1.0,
          dashed: false,
          label: 'reports to',
        });
      }
    }

    // 2. INFERRED: skill_overlap — pairs sharing ≥2 registered skill domains
    const agentIds = agentNodes.map(n => n.id);
    for (let i = 0; i < agentIds.length; i++) {
      for (let j = i + 1; j < agentIds.length; j++) {
        const a = agentIds[i];
        const b = agentIds[j];
        const setA = agentSkillDomains[a] || new Set();
        const setB = agentSkillDomains[b] || new Set();
        if (setA.size === 0 || setB.size === 0) continue;
        const intersection = [...setA].filter(x => setB.has(x));
        if (intersection.length < 2) continue;
        const unionSize = new Set([...setA, ...setB]).size;
        const jaccard = Math.round((intersection.length / unionSize) * 100) / 100;
        edges.push({
          id: `overlap:${a}↔${b}`,
          source: a,
          target: b,
          relation: 'skill_overlap',
          confidence: 'INFERRED',
          confidence_score: jaccard,
          dashed: true,
          label: `${intersection.length} shared skills`,
          sharedSkills: intersection.slice(0, 6),
        });
      }
    }

    // 3. INFERRED: owns_skill — from frontmatter.skills[] (compacted skill files)
    const skillNodesMap = new Map(); // skillId → node

    for (const agent of agents) {
      const agentId = agent.filename.replace(/\.md$/, '');
      const manifest = Array.isArray(agent.frontmatter?.skills) ? agent.frontmatter.skills : [];
      for (const skill of manifest) {
        const rawId = skill.id || skill.path || '';
        const skillId = `skill:${rawId}`;
        if (!skillNodesMap.has(skillId)) {
          skillNodesMap.set(skillId, {
            id: skillId,
            type: 'skill',
            label: rawId.replace(/-/g, ' ').replace(/\b\w/g, c => c.toUpperCase()),
            rawId,
            path: skill.path || '',
            lines: skill.lines || 0,
            department: null,
            departmentLabel: 'Skills',
            departmentColor: '#4b5563',
            community: 97,
            degree: 0,
          });
        }
        edges.push({
          id: `owns:${agentId}→${skillId}`,
          source: agentId,
          target: skillId,
          relation: 'owns_skill',
          confidence: 'INFERRED',
          confidence_score: 0.8,
          dashed: true,
          label: 'owns skill',
        });
      }
    }

    const skillNodes = [...skillNodesMap.values()];

    // ── Degree computation ─────────────────────────────────────────────────────
    const degreeMap = {};
    for (const e of edges) {
      degreeMap[e.source] = (degreeMap[e.source] || 0) + 1;
      degreeMap[e.target] = (degreeMap[e.target] || 0) + 1;
    }
    for (const n of agentNodes) n.degree = degreeMap[n.id] || 0;
    for (const n of skillNodes) n.degree = degreeMap[n.id] || 0;

    // ── Stats ──────────────────────────────────────────────────────────────────
    const allNodes = [...agentNodes, ...skillNodes];
    const extracted = edges.filter(e => e.confidence === 'EXTRACTED').length;
    const inferred = edges.filter(e => e.confidence === 'INFERRED').length;

    // God nodes: agents with degree > mean + 1.5*stddev
    const agentDegrees = agentNodes.map(n => n.degree);
    const meanDegree = agentDegrees.reduce((s, d) => s + d, 0) / Math.max(agentDegrees.length, 1);
    const variance = agentDegrees.reduce((s, d) => s + (d - meanDegree) ** 2, 0) / Math.max(agentDegrees.length, 1);
    const stddev = Math.sqrt(variance);
    const godNodeThreshold = meanDegree + 1.5 * stddev;
    const godNodes = agentNodes
      .filter(n => n.degree >= godNodeThreshold)
      .sort((a, b) => b.degree - a.degree)
      .map(n => ({ id: n.id, label: n.label, degree: n.degree }));

    res.json({
      nodes: allNodes,
      edges,
      stats: {
        totalAgents: agentNodes.length,
        totalSkillNodes: skillNodes.length,
        totalNodes: allNodes.length,
        totalEdges: edges.length,
        byConfidence: { EXTRACTED: extracted, INFERRED: inferred },
        byRelation: {
          reports_to: edges.filter(e => e.relation === 'reports_to').length,
          skill_overlap: edges.filter(e => e.relation === 'skill_overlap').length,
          owns_skill: edges.filter(e => e.relation === 'owns_skill').length,
        },
        communities: deptsBySize.length,
        godNodes,
        meanDegree: Math.round(meanDegree * 10) / 10,
        godNodeThreshold: Math.round(godNodeThreshold * 10) / 10,
      },
      departments: departmentsById,
    });
  } catch (err) {
    res.status(500).json({ error: err.message || 'Knowledge graph build failed' });
  }
});

module.exports = router;

