import { useState, useCallback, useMemo, useRef } from 'react'
import {
  ReactFlow,
  Background,
  Controls,
  MiniMap,
  useNodesState,
  useEdgesState,
  type Node,
  type Edge,
  type NodeTypes,
  Handle,
  Position,
  BackgroundVariant,
  ReactFlowProvider,
  getNodesBounds,
  getViewportForBounds,
} from '@xyflow/react'
import '@xyflow/react/dist/style.css'
import { toPng } from 'html-to-image'
import {
  Network, Search, X, Camera, Eye, EyeOff, Sparkles,
  AlertTriangle, CheckCircle2, BarChart3, ChevronDown, ChevronRight,
  Layers, Zap, RefreshCw, Crown,
} from 'lucide-react'
import { useApi } from '../hooks/useApi'
import { getKnowledgeGraph } from '../lib/api'
import type { KnowledgeGraphNode, KnowledgeGraphEdge, KnowledgeGraphData } from '../lib/api'
import LevelBadge from '../components/LevelBadge'
import { toast } from '../components/Toast'

// ── Constants ─────────────────────────────────────────────────────────────────

const MODEL_COLORS: Record<string, string> = {
  opus: '#a855f7',
  sonnet: '#60a5fa',
  haiku: '#34d399',
}

const TIER_COLORS: Record<string, string> = {
  leadership: '#f59e0b',
  engineer: '#60a5fa',
  analyst: '#a78bfa',
  creative: '#f472b6',
}

// ── Layout ────────────────────────────────────────────────────────────────────

// Groups agents by community (department), then arranges groups in a grid.
// Within each group, agents are stacked vertically. Skill nodes orbit around
// their agent in a small fan layout.
function computeLayout(
  nodes: KnowledgeGraphNode[],
  edges: KnowledgeGraphEdge[],
  showSkills: boolean,
): { rfNodes: Node[]; rfEdges: Edge[] } {
  const agentNodes = nodes.filter(n => n.type === 'agent')
  const skillNodes = nodes.filter(n => n.type === 'skill')

  // Group agents by community
  const groups = new Map<number, KnowledgeGraphNode[]>()
  for (const n of agentNodes) {
    const c = n.community
    if (!groups.has(c)) groups.set(c, [])
    groups.get(c)!.push(n)
  }
  const sortedGroups = [...groups.entries()].sort((a, b) => a[0] - b[0])

  const NODE_W = 200
  const NODE_H = 72
  const GROUP_PADDING = 24
  const GROUP_GAP_X = 60
  const GROUP_GAP_Y = 60
  const COLS = Math.ceil(Math.sqrt(sortedGroups.length))

  let positions: Record<string, { x: number; y: number }> = {}

  let groupRow = 0
  let groupCol = 0
  let colX = GROUP_PADDING

  // Track cumulative heights per column for stacking groups vertically
  const colHeights: number[] = Array(COLS).fill(GROUP_PADDING)

  for (const [, members] of sortedGroups) {
    // Sort: leaders first, then by level desc, then alpha
    members.sort((a, b) => {
      if ((b.level ?? -1) !== (a.level ?? -1)) return (b.level ?? -1) - (a.level ?? -1)
      return a.label.localeCompare(b.label)
    })

    const col = groupCol % COLS
    const groupX = col * (NODE_W + GROUP_GAP_X) + GROUP_PADDING
    const groupY = colHeights[col]

    members.forEach((m, i) => {
      positions[m.id] = {
        x: groupX,
        y: groupY + i * (NODE_H + 8),
      }
    })

    colHeights[col] += members.length * (NODE_H + 8) + GROUP_GAP_Y

    groupCol++
    if (groupCol % COLS === 0) {
      groupRow++
    }
    void groupRow // suppress unused warning
  }

  // Skill nodes: fan out from their owning agent
  if (showSkills) {
    const ownsEdges = edges.filter(e => e.relation === 'owns_skill')
    const agentToSkills: Record<string, string[]> = {}
    for (const e of ownsEdges) {
      if (!agentToSkills[e.source]) agentToSkills[e.source] = []
      agentToSkills[e.source].push(e.target)
    }
    for (const [agentId, skillIds] of Object.entries(agentToSkills)) {
      const ap = positions[agentId]
      if (!ap) continue
      skillIds.forEach((sid, i) => {
        const angle = (Math.PI / (skillIds.length + 1)) * (i + 1)
        const r = 140
        positions[sid] = {
          x: ap.x + r * Math.cos(angle),
          y: ap.y + r * Math.sin(angle) + NODE_H / 2,
        }
      })
    }
  }

  // Build React Flow nodes
  const rfNodes: Node[] = []

  for (const n of agentNodes) {
    const pos = positions[n.id] || { x: 0, y: 0 }
    rfNodes.push({
      id: n.id,
      type: 'agentNode',
      position: pos,
      data: n,
      width: NODE_W,
      height: NODE_H,
    })
  }

  if (showSkills) {
    for (const n of skillNodes) {
      const pos = positions[n.id]
      if (!pos) continue
      rfNodes.push({
        id: n.id,
        type: 'skillNode',
        position: pos,
        data: n,
        width: 160,
        height: 36,
      })
    }
  }

  // Build React Flow edges
  const activeNodeIds = new Set(rfNodes.map(n => n.id))
  const rfEdges: Edge[] = edges
    .filter(e => activeNodeIds.has(e.source) && activeNodeIds.has(e.target))
    .map(e => ({
      id: e.id,
      source: e.source,
      target: e.target,
      label: e.relation === 'skill_overlap' ? `${e.sharedSkills?.length || 0} shared` : undefined,
      style: {
        stroke:
          e.confidence === 'EXTRACTED' ? '#6366f1'
          : e.relation === 'skill_overlap' ? '#f59e0b'
          : '#4b5563',
        strokeWidth: e.confidence === 'EXTRACTED' ? 2 : 1,
        strokeDasharray: e.dashed ? '4 3' : undefined,
        opacity: e.confidence === 'EXTRACTED' ? 0.9 : 0.4,
      },
      type: 'default',
      animated: false,
      data: e,
    }))

  return { rfNodes, rfEdges }
}

// ── Custom Node: Agent ────────────────────────────────────────────────────────

function AgentGraphNode({ data, selected }: { data: KnowledgeGraphNode; selected?: boolean }) {
  const isGod = data.degree >= 8 // rough threshold, refined below
  const modelColor = MODEL_COLORS[data.model || 'sonnet'] || '#60a5fa'
  const deptColor = data.departmentColor || '#6b7280'

  return (
    <div
      className={`relative bg-surface border rounded-xl px-3 py-2 cursor-pointer transition-all select-none ${
        selected
          ? 'border-accent shadow-lg shadow-accent/20 ring-1 ring-accent/40'
          : 'border-border hover:border-border/80'
      }`}
      style={{ width: 200, minHeight: 72, borderLeft: `3px solid ${deptColor}` }}
    >
      <Handle type="target" position={Position.Top} style={{ opacity: 0 }} />
      <Handle type="source" position={Position.Bottom} style={{ opacity: 0 }} />

      {/* Header row */}
      <div className="flex items-center gap-2 mb-1">
        <div
          className="w-5 h-5 rounded-full shrink-0 flex items-center justify-center text-[10px] font-bold text-white"
          style={{ background: deptColor }}
        >
          {data.label.charAt(0).toUpperCase()}
        </div>
        <span className="text-[11px] font-semibold truncate flex-1">{data.id}</span>
        {isGod && <Crown className="w-3 h-3 text-amber-400 shrink-0" title="High-connectivity node" />}
      </div>

      {/* Badges row */}
      <div className="flex items-center gap-1 flex-wrap">
        <span
          className="px-1.5 py-0.5 rounded text-[8px] font-mono font-semibold"
          style={{ background: `${modelColor}22`, color: modelColor }}
        >
          {data.model || 'sonnet'}
        </span>
        {data.level != null && (
          <span className="px-1 py-0.5 rounded text-[8px] font-semibold bg-accent/10 text-accent">
            L{data.level}
          </span>
        )}
        {data.tier && (
          <span
            className="px-1 py-0.5 rounded text-[8px] font-semibold"
            style={{ background: `${TIER_COLORS[data.tier] || '#6b7280'}22`, color: TIER_COLORS[data.tier] || '#6b7280' }}
          >
            {data.tier}
          </span>
        )}
        <span className="ml-auto text-[8px] text-text-muted font-mono">{data.degree}↔</span>
      </div>

      {/* Dept label */}
      <p className="text-[9px] text-text-muted truncate mt-0.5">{data.departmentLabel}</p>
    </div>
  )
}

// ── Custom Node: Skill ────────────────────────────────────────────────────────

function SkillGraphNode({ data, selected }: { data: KnowledgeGraphNode; selected?: boolean }) {
  return (
    <div
      className={`bg-surface-2 border rounded-lg px-2 py-1 cursor-pointer text-[9px] truncate select-none transition-all ${
        selected ? 'border-accent' : 'border-border/50'
      }`}
      style={{ width: 160, maxWidth: 160 }}
      title={data.label}
    >
      <Handle type="target" position={Position.Top} style={{ opacity: 0 }} />
      <span className="text-text-muted font-mono truncate block">{data.label.slice(0, 28)}</span>
    </div>
  )
}

const nodeTypes: NodeTypes = {
  agentNode: AgentGraphNode as unknown as NodeTypes['agentNode'],
  skillNode: SkillGraphNode as unknown as NodeTypes['skillNode'],
}

// ── Inspector Sidebar ─────────────────────────────────────────────────────────

function NodeInspector({
  node,
  edges,
  allNodes,
  onClose,
  onSelectNode,
}: {
  node: KnowledgeGraphNode
  edges: KnowledgeGraphEdge[]
  allNodes: KnowledgeGraphNode[]
  onClose: () => void
  onSelectNode: (id: string) => void
}) {
  const nodeById = useMemo(() => new Map(allNodes.map(n => [n.id, n])), [allNodes])
  const connectedEdges = edges.filter(e => e.source === node.id || e.target === node.id)
  const neighbors = connectedEdges.map(e => {
    const neighborId = e.source === node.id ? e.target : e.source
    return { edge: e, neighbor: nodeById.get(neighborId) }
  }).filter(x => x.neighbor)

  const reportsToNode = node.reportsTo ? nodeById.get(node.reportsTo) : null
  const directReports = allNodes.filter(n => n.reportsTo === node.id)

  return (
    <div className="flex flex-col h-full">
      {/* Header */}
      <div className="flex items-center justify-between px-4 py-3 border-b border-border shrink-0">
        <div className="flex items-center gap-2">
          <div
            className="w-6 h-6 rounded-lg flex items-center justify-center text-[11px] font-bold text-white"
            style={{ background: node.departmentColor }}
          >
            {node.id.charAt(0).toUpperCase()}
          </div>
          <div>
            <p className="text-[13px] font-semibold">{node.id}</p>
            <p className="text-[10px] text-text-muted">{node.type === 'skill' ? 'Skill Node' : node.departmentLabel}</p>
          </div>
        </div>
        <button onClick={onClose} className="p-1 rounded hover:bg-surface-2 text-text-muted hover:text-text">
          <X className="w-4 h-4" />
        </button>
      </div>

      <div className="flex-1 overflow-y-auto">
        {node.type === 'agent' ? (
          <div className="p-4 space-y-4">
            {/* Core metrics */}
            <div className="grid grid-cols-2 gap-2">
              <MetricCard label="Level" value={node.level != null ? `L${node.level}` : '—'} sub={node.levelTitle || ''} />
              <MetricCard label="Tier" value={node.tier || '—'} />
              <MetricCard label="Connections" value={`${node.degree}`} sub="degree" />
              <MetricCard label="Experience" value={node.yearsOfExperience != null ? `${node.yearsOfExperience}y` : '—'} />
              <MetricCard label="Skill Files" value={`${node.skillFileCount || 0}`} sub="compacted" />
              <MetricCard label="Skill Domains" value={`${node.registeredSkillCount || 0}`} sub="registered" />
            </div>

            {node.description && (
              <p className="text-[11px] text-text-muted leading-relaxed">{node.description}</p>
            )}

            {/* Level badge */}
            <div>
              <LevelBadge
                level={node.level}
                title={node.levelTitle || undefined}
                status={(node.status as 'active' | 'probation' | 'pip' | 'retired') || 'active'}
                yearsOfExperience={node.yearsOfExperience}
                showYoE
                size="sm"
              />
            </div>

            {/* Hierarchy */}
            {reportsToNode && (
              <div>
                <p className="text-[10px] font-semibold text-text-muted uppercase tracking-wider mb-1.5">Reports to</p>
                <button
                  onClick={() => onSelectNode(reportsToNode.id)}
                  className="flex items-center gap-2 text-[11px] text-accent hover:underline"
                >
                  <div className="w-4 h-4 rounded-full shrink-0" style={{ background: reportsToNode.departmentColor }} />
                  {reportsToNode.id}
                </button>
              </div>
            )}

            {directReports.length > 0 && (
              <div>
                <p className="text-[10px] font-semibold text-text-muted uppercase tracking-wider mb-1.5">
                  Direct reports ({directReports.length})
                </p>
                <div className="space-y-1">
                  {directReports.map(r => (
                    <button
                      key={r.id}
                      onClick={() => onSelectNode(r.id)}
                      className="flex items-center gap-2 text-[11px] text-text-secondary hover:text-accent w-full text-left"
                    >
                      <div className="w-3 h-3 rounded-full shrink-0" style={{ background: r.departmentColor }} />
                      {r.id}
                    </button>
                  ))}
                </div>
              </div>
            )}

            {/* Skill overlaps */}
            {neighbors.filter(n => n.edge.relation === 'skill_overlap').length > 0 && (
              <div>
                <p className="text-[10px] font-semibold text-text-muted uppercase tracking-wider mb-1.5">
                  Skill overlap with
                </p>
                <div className="space-y-1.5">
                  {neighbors
                    .filter(n => n.edge.relation === 'skill_overlap')
                    .sort((a, b) => b.edge.confidence_score - a.edge.confidence_score)
                    .slice(0, 8)
                    .map(({ edge, neighbor }) => (
                      <button
                        key={neighbor!.id}
                        onClick={() => onSelectNode(neighbor!.id)}
                        className="w-full text-left"
                      >
                        <div className="flex items-center justify-between">
                          <span className="text-[11px] text-text-secondary hover:text-accent">{neighbor!.id}</span>
                          <span className="text-[9px] font-mono text-text-muted">{Math.round(edge.confidence_score * 100)}%</span>
                        </div>
                        {edge.sharedSkills && edge.sharedSkills.length > 0 && (
                          <div className="flex flex-wrap gap-1 mt-0.5">
                            {edge.sharedSkills.slice(0, 3).map(s => (
                              <span key={s} className="text-[8px] bg-amber-500/10 text-amber-400 px-1 py-0.5 rounded">
                                {s}
                              </span>
                            ))}
                          </div>
                        )}
                      </button>
                    ))}
                </div>
              </div>
            )}
          </div>
        ) : (
          /* Skill node inspector */
          <div className="p-4 space-y-3">
            <MetricCard label="Lines" value={`${node.lines || 0}`} sub="in skill file" />
            <MetricCard label="Referenced by" value={`${node.degree}`} sub="agents" />
            {node.path && (
              <div>
                <p className="text-[10px] font-semibold text-text-muted uppercase tracking-wider mb-1">Path</p>
                <p className="text-[10px] font-mono text-text-secondary break-all">{node.path}</p>
              </div>
            )}
            <div>
              <p className="text-[10px] font-semibold text-text-muted uppercase tracking-wider mb-1.5">Owned by</p>
              <div className="space-y-1">
                {neighbors.map(({ neighbor }) => neighbor && (
                  <button
                    key={neighbor.id}
                    onClick={() => onSelectNode(neighbor.id)}
                    className="flex items-center gap-2 text-[11px] text-text-secondary hover:text-accent w-full text-left"
                  >
                    <div className="w-3 h-3 rounded-full shrink-0" style={{ background: neighbor.departmentColor }} />
                    {neighbor.id}
                  </button>
                ))}
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  )
}

function MetricCard({ label, value, sub }: { label: string; value: string; sub?: string }) {
  return (
    <div className="bg-surface-2 rounded-lg px-3 py-2">
      <p className="text-[9px] font-semibold uppercase tracking-wider text-text-muted">{label}</p>
      <p className="text-[13px] font-mono font-semibold text-text mt-0.5">{value}</p>
      {sub && <p className="text-[9px] text-text-muted">{sub}</p>}
    </div>
  )
}

// ── Stats Panel ───────────────────────────────────────────────────────────────

function StatsPanel({ data }: { data: KnowledgeGraphData }) {
  const [expanded, setExpanded] = useState(false)
  const s = data.stats

  return (
    <div className="border-b border-border">
      <button
        onClick={() => setExpanded(!expanded)}
        className="w-full flex items-center justify-between px-4 py-2.5 hover:bg-surface-2/40 transition-colors"
      >
        <div className="flex items-center gap-2">
          <BarChart3 className="w-3.5 h-3.5 text-text-muted" />
          <span className="text-[11px] font-semibold">Graph Stats</span>
        </div>
        <div className="flex items-center gap-2">
          <span className="text-[10px] text-text-muted font-mono">{s.totalNodes}N · {s.totalEdges}E</span>
          {expanded ? <ChevronDown className="w-3.5 h-3.5 text-text-muted" /> : <ChevronRight className="w-3.5 h-3.5 text-text-muted" />}
        </div>
      </button>
      {expanded && (
        <div className="px-4 pb-3 space-y-2">
          {/* Confidence breakdown */}
          <div className="flex items-center gap-2">
            <div className="flex-1 h-1.5 bg-surface-3 rounded-full overflow-hidden">
              <div
                className="h-full bg-accent rounded-full"
                style={{ width: `${s.totalEdges > 0 ? (s.byConfidence.EXTRACTED / s.totalEdges * 100) : 0}%` }}
              />
            </div>
            <span className="text-[9px] font-mono text-text-muted w-20 text-right">
              {s.byConfidence.EXTRACTED} EXTRACTED
            </span>
          </div>
          <div className="flex items-center gap-2">
            <div className="flex-1 h-1.5 bg-surface-3 rounded-full overflow-hidden">
              <div
                className="h-full bg-amber-500 rounded-full"
                style={{ width: `${s.totalEdges > 0 ? (s.byConfidence.INFERRED / s.totalEdges * 100) : 0}%` }}
              />
            </div>
            <span className="text-[9px] font-mono text-text-muted w-20 text-right">
              {s.byConfidence.INFERRED} INFERRED
            </span>
          </div>
          {/* By relation */}
          <div className="grid grid-cols-3 gap-1.5 mt-2">
            {Object.entries(s.byRelation).map(([rel, count]) => (
              <div key={rel} className="bg-surface-2 rounded px-2 py-1 text-center">
                <p className="text-[11px] font-mono font-bold text-text">{count}</p>
                <p className="text-[8px] text-text-muted">{rel.replace(/_/g, ' ')}</p>
              </div>
            ))}
          </div>
          {/* God nodes */}
          {s.godNodes.length > 0 && (
            <div>
              <p className="text-[9px] font-semibold text-text-muted uppercase tracking-wider mb-1 flex items-center gap-1">
                <Crown className="w-3 h-3 text-amber-400" /> God Nodes (degree ≥ {s.godNodeThreshold})
              </p>
              {s.godNodes.slice(0, 5).map(n => (
                <div key={n.id} className="flex items-center justify-between py-0.5">
                  <span className="text-[10px] text-text-secondary">{n.id}</span>
                  <span className="text-[9px] font-mono text-amber-400">{n.degree}↔</span>
                </div>
              ))}
            </div>
          )}
        </div>
      )}
    </div>
  )
}

// ── Main Component ────────────────────────────────────────────────────────────

function KnowledgeGraphInner() {
  const { data: graphData, loading, refetch } = useApi(getKnowledgeGraph)

  const [search, setSearch] = useState('')
  const [showSkills, setShowSkills] = useState(false)
  const [hideInferred, setHideInferred] = useState(false)
  const [hiddenDepts, setHiddenDepts] = useState<Set<string>>(new Set())
  const [selectedNodeId, setSelectedNodeId] = useState<string | null>(null)
  const [inspectorOpen, setInspectorOpen] = useState(false)
  const rfRef = useRef<HTMLDivElement>(null)

  // Filtered graph data
  const filteredData = useMemo(() => {
    if (!graphData) return null

    let nodes = graphData.nodes.filter(n => {
      if (n.type === 'skill' && !showSkills) return false
      if (n.department && hiddenDepts.has(n.department)) return false
      return true
    })

    if (search.trim()) {
      const q = search.toLowerCase()
      const matchedIds = new Set(nodes.filter(n => n.id.includes(q) || n.label.toLowerCase().includes(q) || n.departmentLabel?.toLowerCase().includes(q)).map(n => n.id))
      // Also include neighbors of matched nodes for context
      nodes = nodes.filter(n => matchedIds.has(n.id))
    }

    const nodeIds = new Set(nodes.map(n => n.id))
    let edges = graphData.edges.filter(e => nodeIds.has(e.source) && nodeIds.has(e.target))
    if (hideInferred) edges = edges.filter(e => e.confidence === 'EXTRACTED')

    return { nodes, edges }
  }, [graphData, search, showSkills, hideInferred, hiddenDepts])

  // Compute god node threshold for highlighting
  const godNodeIds = useMemo(() => {
    if (!graphData) return new Set<string>()
    return new Set(graphData.stats.godNodes.map(n => n.id))
  }, [graphData])

  // Layout
  const { rfNodes: initialNodes, rfEdges: initialEdges } = useMemo(() => {
    if (!filteredData) return { rfNodes: [], rfEdges: [] }
    const result = computeLayout(filteredData.nodes, filteredData.edges, showSkills)
    // Highlight god nodes
    return {
      rfNodes: result.rfNodes.map(n => ({
        ...n,
        data: { ...n.data, isGod: godNodeIds.has(n.id), degree: (n.data as KnowledgeGraphNode).degree },
      })),
      rfEdges: result.rfEdges,
    }
  }, [filteredData, showSkills, godNodeIds])

  const [nodes, , onNodesChange] = useNodesState(initialNodes)
  const [edges, , onEdgesChange] = useEdgesState(initialEdges)

  // Sync when layout changes
  const prevLayoutKey = useRef('')
  const layoutKey = `${filteredData?.nodes.length}-${filteredData?.edges.length}-${showSkills}`
  if (layoutKey !== prevLayoutKey.current) {
    prevLayoutKey.current = layoutKey
  }

  const selectedNode = useMemo(
    () => graphData?.nodes.find(n => n.id === selectedNodeId) || null,
    [graphData, selectedNodeId]
  )

  const handleNodeClick = useCallback((_: React.MouseEvent, node: Node) => {
    setSelectedNodeId(node.id)
    setInspectorOpen(true)
  }, [])

  const handleExport = useCallback(async () => {
    if (!rfRef.current) return
    try {
      const nodesBounds = getNodesBounds(nodes)
      const viewport = getViewportForBounds(nodesBounds, 1920, 1080, 0.5, 2, 0.1)
      const dataUrl = await toPng(rfRef.current.querySelector('.react-flow__viewport') as HTMLElement, {
        backgroundColor: '#0f0f1a',
        width: 1920,
        height: 1080,
        style: { transform: `translate(${viewport.x}px, ${viewport.y}px) scale(${viewport.zoom})` },
      })
      const a = document.createElement('a')
      a.href = dataUrl
      a.download = 'knowledge-graph.png'
      a.click()
      toast('success', 'Exported graph')
    } catch {
      toast('error', 'Export failed')
    }
  }, [nodes])

  const toggleDept = useCallback((deptId: string) => {
    setHiddenDepts(prev => {
      const next = new Set(prev)
      if (next.has(deptId)) next.delete(deptId)
      else next.add(deptId)
      return next
    })
  }, [])

  if (loading) {
    return (
      <div className="flex-1 flex items-center justify-center h-full">
        <div className="w-6 h-6 border-2 border-accent border-t-transparent rounded-full animate-spin" />
      </div>
    )
  }

  if (!graphData) {
    return (
      <div className="flex-1 flex items-center justify-center h-full text-text-muted">
        Failed to load knowledge graph
      </div>
    )
  }

  const departments = Object.entries(graphData.departments)

  return (
    <div className="flex h-screen overflow-hidden">
      {/* ── Left sidebar ─────────────────────────────────────────────────────── */}
      <aside className="w-[240px] min-w-[240px] border-r border-border bg-surface flex flex-col h-full overflow-hidden">
        {/* Header */}
        <div className="px-4 py-3 border-b border-border shrink-0">
          <div className="flex items-center gap-2 mb-3">
            <Network className="w-4 h-4 text-accent" />
            <h1 className="text-[13px] font-semibold">Knowledge Graph</h1>
            <button
              onClick={() => { refetch(); toast('success', 'Refreshed') }}
              className="ml-auto p-1 rounded text-text-muted hover:text-text hover:bg-surface-2"
              title="Refresh"
            >
              <RefreshCw className="w-3.5 h-3.5" />
            </button>
          </div>
          {/* Search */}
          <div className="relative">
            <Search className="w-3.5 h-3.5 text-text-muted absolute left-2.5 top-1/2 -translate-y-1/2" />
            <input
              value={search}
              onChange={e => setSearch(e.target.value)}
              placeholder="Search nodes..."
              className="w-full bg-surface-2 border border-border rounded-lg pl-8 pr-8 py-1.5 text-[12px] focus:outline-none focus:border-accent/50"
            />
            {search && (
              <button onClick={() => setSearch('')} className="absolute right-2 top-1/2 -translate-y-1/2 text-text-muted hover:text-text">
                <X className="w-3 h-3" />
              </button>
            )}
          </div>
        </div>

        {/* Stats */}
        <StatsPanel data={graphData} />

        {/* Toggles */}
        <div className="px-4 py-2.5 border-b border-border shrink-0 space-y-2">
          <p className="text-[10px] font-semibold text-text-muted uppercase tracking-wider">Display</p>
          <label className="flex items-center gap-2 cursor-pointer">
            <input
              type="checkbox"
              checked={showSkills}
              onChange={e => setShowSkills(e.target.checked)}
              className="w-3.5 h-3.5 accent-accent"
            />
            <div className="flex items-center gap-1.5">
              <Layers className="w-3 h-3 text-text-muted" />
              <span className="text-[11px]">Show skill nodes</span>
            </div>
          </label>
          <label className="flex items-center gap-2 cursor-pointer">
            <input
              type="checkbox"
              checked={hideInferred}
              onChange={e => setHideInferred(e.target.checked)}
              className="w-3.5 h-3.5 accent-accent"
            />
            <div className="flex items-center gap-1.5">
              {hideInferred ? <EyeOff className="w-3 h-3 text-text-muted" /> : <Eye className="w-3 h-3 text-text-muted" />}
              <span className="text-[11px]">EXTRACTED only</span>
            </div>
          </label>
        </div>

        {/* Legend */}
        <div className="px-4 py-2.5 border-b border-border shrink-0 space-y-1.5">
          <p className="text-[10px] font-semibold text-text-muted uppercase tracking-wider mb-2">Edge types</p>
          <div className="flex items-center gap-2">
            <div className="w-8 h-0.5 bg-accent rounded" />
            <span className="text-[10px] text-text-muted">reports_to (EXTRACTED)</span>
          </div>
          <div className="flex items-center gap-2">
            <div className="w-8 h-0.5 bg-amber-500 rounded border-dashed border-t border-amber-500" style={{ borderStyle: 'dashed' }} />
            <span className="text-[10px] text-text-muted">skill_overlap (INFERRED)</span>
          </div>
          <div className="flex items-center gap-2">
            <div className="w-8 h-0.5 bg-zinc-500 rounded" style={{ borderStyle: 'dashed' }} />
            <span className="text-[10px] text-text-muted">owns_skill (INFERRED)</span>
          </div>
        </div>

        {/* Department filters */}
        <div className="flex-1 overflow-y-auto px-4 py-2.5 space-y-1">
          <p className="text-[10px] font-semibold text-text-muted uppercase tracking-wider mb-2">Departments</p>
          {departments.map(([deptId, dept]) => {
            const hidden = hiddenDepts.has(deptId)
            return (
              <button
                key={deptId}
                onClick={() => toggleDept(deptId)}
                className={`w-full flex items-center gap-2 px-2 py-1.5 rounded-lg text-[11px] transition-colors ${
                  hidden ? 'opacity-40 hover:opacity-60' : 'hover:bg-surface-2'
                }`}
              >
                <div className="w-2.5 h-2.5 rounded-full shrink-0" style={{ background: dept.color }} />
                <span className="flex-1 text-left truncate text-text-secondary">{dept.label}</span>
                {hidden ? <EyeOff className="w-3 h-3 text-text-muted" /> : <Eye className="w-3 h-3 text-text-muted/40" />}
              </button>
            )
          })}
        </div>

        {/* Export */}
        <div className="border-t border-border p-3 shrink-0">
          <button
            onClick={handleExport}
            className="w-full flex items-center justify-center gap-2 px-3 py-2 text-[11px] font-medium bg-surface-2 hover:bg-surface-3 rounded-lg transition-colors"
          >
            <Camera className="w-3.5 h-3.5" /> Export PNG
          </button>
        </div>
      </aside>

      {/* ── Graph canvas ──────────────────────────────────────────────────────── */}
      <div className="flex-1 relative" ref={rfRef}>
        <ReactFlow
          nodes={initialNodes}
          edges={initialEdges}
          onNodesChange={onNodesChange}
          onEdgesChange={onEdgesChange}
          onNodeClick={handleNodeClick}
          onPaneClick={() => { setSelectedNodeId(null); setInspectorOpen(false) }}
          nodeTypes={nodeTypes}
          fitView
          fitViewOptions={{ padding: 0.15 }}
          minZoom={0.1}
          maxZoom={2}
          proOptions={{ hideAttribution: true }}
        >
          <Background variant={BackgroundVariant.Dots} gap={20} size={1} className="opacity-30" />
          <Controls className="!bottom-4 !left-4" />
          <MiniMap
            className="!bottom-4 !right-4 !bg-surface !border !border-border"
            nodeColor={n => {
              const d = n.data as KnowledgeGraphNode
              return d.departmentColor || '#4b5563'
            }}
            maskColor="rgba(0,0,0,0.5)"
          />
        </ReactFlow>

        {/* Overlay stats badge */}
        <div className="absolute top-3 left-3 flex items-center gap-2 pointer-events-none">
          <div className="bg-surface/80 backdrop-blur border border-border rounded-lg px-3 py-1.5 flex items-center gap-3">
            <div className="flex items-center gap-1.5 text-[10px] font-mono text-text-muted">
              <Sparkles className="w-3 h-3 text-accent" />
              <span className="text-text">{graphData.stats.totalAgents}</span> agents
            </div>
            <div className="w-px h-3 bg-border" />
            <div className="flex items-center gap-1 text-[10px] font-mono">
              <CheckCircle2 className="w-3 h-3 text-accent" />
              <span className="text-text">{graphData.stats.byConfidence.EXTRACTED}</span>
              <span className="text-text-muted">extracted</span>
            </div>
            <div className="w-px h-3 bg-border" />
            <div className="flex items-center gap-1 text-[10px] font-mono">
              <AlertTriangle className="w-3 h-3 text-amber-400" />
              <span className="text-text">{graphData.stats.byConfidence.INFERRED}</span>
              <span className="text-text-muted">inferred</span>
            </div>
            {showSkills && (
              <>
                <div className="w-px h-3 bg-border" />
                <div className="flex items-center gap-1 text-[10px] font-mono">
                  <Zap className="w-3 h-3 text-blue-400" />
                  <span className="text-text">{graphData.stats.totalSkillNodes}</span>
                  <span className="text-text-muted">skills</span>
                </div>
              </>
            )}
          </div>
        </div>
      </div>

      {/* ── Right inspector ───────────────────────────────────────────────────── */}
      {inspectorOpen && selectedNode && (
        <aside className="w-[280px] min-w-[280px] border-l border-border bg-surface flex flex-col h-full overflow-hidden">
          <NodeInspector
            node={selectedNode}
            edges={graphData.edges}
            allNodes={graphData.nodes}
            onClose={() => { setInspectorOpen(false); setSelectedNodeId(null) }}
            onSelectNode={id => { setSelectedNodeId(id) }}
          />
        </aside>
      )}
    </div>
  )
}

export default function KnowledgeGraph() {
  return (
    <ReactFlowProvider>
      <KnowledgeGraphInner />
    </ReactFlowProvider>
  )
}

